//! The relations' parameters (plan D8), generated by `pqzl/params/to_rust.py` from LaZer's codegen headers
//! `pqzl/params/pqz_*_params.h`: one module per header, the C names lower-cased (`pqz_tx_Bsq` -> `pqz_tx_bsq`), the
//! structs below field for field as lazer-in2.h's (`polyring_t`, `dcompress_params_t` = `coder::Dcomp`,
//! `abdlop_params_t`, `lnp_quad_eval_params_t`, `lnp_tbox_params_t`). Do not edit: regenerate with
//! `python3 -I pqz-core/pqzl/params/to_rust.py` (the test run checks with `--check`). `tests/oracle_params.rs` reads
//! every field of every relation back through the C core's headers.
#![allow(non_upper_case_globals)]
pub(crate) use crate::arith::int::Int;
pub(crate) use crate::coder::Dcomp;

/// `polyring_t`; `moduli` (the dropped CRT moduli: `moduli_d64`, a null pointer in the fork) has no field
#[derive(Debug)]
pub(crate) struct Ring {
    pub(crate) q: Int,
    pub(crate) d: u32,
    pub(crate) log2q: u32,
    pub(crate) log2d: u32,
    pub(crate) nmoduli: u32,
    pub(crate) pmodq: Int,
    /// `nmoduli` entries
    pub(crate) ppmodq: &'static [Int],
    pub(crate) inv2: Int,
}

/// `abdlop_params_t`
#[derive(Debug)]
pub(crate) struct Abdlop {
    pub(crate) ring: &'static Ring,
    pub(crate) dcompress: &'static Dcomp,
    pub(crate) m1: u32,
    pub(crate) m2: u32,
    pub(crate) l: u32,
    pub(crate) lext: u32,
    pub(crate) kmsis: u32,
    pub(crate) bsqr: Int,
    pub(crate) nu: i64,
    pub(crate) omega: i64,
    pub(crate) log2omega: u32,
    pub(crate) eta: u64,
    pub(crate) rej1: i32,
    pub(crate) log2stdev1: u32,
    pub(crate) scm1: Int,
    pub(crate) stdev1sqr: Int,
    pub(crate) rej2: i32,
    pub(crate) log2stdev2: u32,
    pub(crate) scm2: Int,
    pub(crate) stdev2sqr: Int,
}

/// `lnp_quad_eval_params_t`
#[derive(Debug)]
pub(crate) struct QuadEval {
    pub(crate) quad_eval: &'static Abdlop,
    pub(crate) quad_many: &'static Abdlop,
    pub(crate) lambda: u32,
}

/// `lnp_tbox_params_t`
#[derive(Debug)]
pub(crate) struct Tbox {
    pub(crate) tbox: &'static Abdlop,
    pub(crate) quad_eval: &'static QuadEval,
    pub(crate) nbin: u32,
    /// `z` entries
    pub(crate) n: &'static [u32],
    pub(crate) nprime: u32,
    pub(crate) z: u32,
    pub(crate) nex: u32,
    pub(crate) rej3: i32,
    pub(crate) log2stdev3: u32,
    pub(crate) scm3: Int,
    pub(crate) stdev3sqr: Int,
    pub(crate) rej4: i32,
    pub(crate) log2stdev4: u32,
    pub(crate) scm4: Int,
    pub(crate) stdev4sqr: Int,
    pub(crate) bz3sqr: Int,
    pub(crate) bz4: Int,
    /// `z` entries
    pub(crate) l2bsqr: &'static [Int],
    pub(crate) inv4: Int,
    pub(crate) prooflen: u64,
}

pub(crate) mod burn;
pub(crate) mod dr;
pub(crate) mod ds;
pub(crate) mod reg;
pub(crate) mod tx;
pub(crate) mod tx0;
pub(crate) mod txm2;
pub(crate) mod txm20;
pub(crate) mod txm4;
pub(crate) mod txm40;
pub(crate) mod txm8;
pub(crate) mod txm80;
pub(crate) mod txm80g1;
pub(crate) mod txm8g1;
